// Who is talking, what they want, and which meal slot they mean (Paris time).
const msg = $input.first().json.message || {};
const chatId = String((msg.chat || {}).id || '');
const prenom = (msg.from || {}).first_name || '';
const texte = String(msg.text || '').trim();
const bas = texte.toLowerCase().replace(/@\w+/, '');

const ORDRE = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
const EN = { Mon: 'Lun', Tue: 'Mar', Wed: 'Mer', Thu: 'Jeu', Fri: 'Ven', Sat: 'Sam', Sun: 'Dim' };
const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', weekday: 'short', hour: '2-digit', hour12: false }).formatToParts(new Date());
let jour = EN[parts.find(function (p) { return p.type === 'weekday'; }).value];
const heure = Number(parts.find(function (p) { return p.type === 'hour'; }).value);
let moment = heure < 15 ? 'midi' : 'soir';
const MOTS_JOURS = [[/\b(lundi|monday|mon)\b/, 'Lun'], [/\b(mardi|tuesday|tue)\b/, 'Mar'], [/\b(mercredi|wednesday|wed)\b/, 'Mer'],
  [/\b(jeudi|thursday|thu)\b/, 'Jeu'], [/\b(vendredi|friday|fri)\b/, 'Ven'], [/\b(samedi|saturday|sat)\b/, 'Sam'], [/\b(dimanche|sunday|sun)\b/, 'Dim']];
if (/\b(demain|tomorrow)\b/.test(bas)) jour = ORDRE[(ORDRE.indexOf(jour) + 1) % 7];
MOTS_JOURS.forEach(function (m) { if (m[0].test(bas)) jour = m[1]; });
if (/\b(midi|lunch|d[ée]j(euner)?)\b/.test(bas)) moment = 'midi';
if (/\b(soir|dinner|d[iî]ner|tonight)\b/.test(bas)) moment = 'soir';

// Intent. Short exact words first (they drive a cooking session), then commands, then free text.
let intention = 'question', reference = '', minutes = 0;
const lienSite = texte.match(/^\/start\s+(mp-\S+)/i);
if (lienSite) { intention = 'lier'; reference = lienSite[1].toUpperCase(); }
else if (/^\/?(next|n|suivant|suivante|ok|done|fait|go|continue)\s*[.!]*$/.test(bas)) intention = 'suivant';
else if (/^\/?(back|b|prev|previous|retour|pr[ée]c[ée]dent)\s*[.!]*$/.test(bas)) intention = 'precedent';
else if (/^\/?(repeat|r|again|r[ée]p[eè]te)\s*[.!?]*$/.test(bas)) intention = 'repeter';
else if (/^\/(stop|end|fin)\b/.test(bas)) intention = 'stop';
else if (/^\/(start|help|aide|menu)\b/.test(bas) || /^(help|aide|menu)$/.test(bas)) intention = 'aide';
else if (/^\/link\b/.test(bas)) { intention = 'lier'; reference = String(texte.split(/\s+/)[1] || '').toUpperCase(); }
else if (/^\/(timer|minuteur)\b/.test(bas) || /^(timer|minuteur)\b/.test(bas)) {
  intention = 'minuteur'; const n = bas.match(/(\d+)/); minutes = n ? Number(n[1]) : 0;
}
else if (/^\/(cook|cuisiner)\b/.test(bas) || /^(let'?s cook|start cooking|on cuisine|cook)\b/.test(bas)) intention = 'cuisiner';
else if (/^\/(recipe|recette|steps)\b/.test(bas) || /^(recipe|recette)\b/.test(bas)) intention = 'recette';
else if (/^\/(ingredients|ingr[ée]dients)\b/.test(bas) || /^ingr[ée]dients?\b/.test(bas)) intention = 'ingredients';
else if (/^\/(week|semaine)\b/.test(bas) || /\b(my week|this week|ma semaine|cette semaine)\b/.test(bas)) intention = 'semaine';
else if (/^\/(list|courses|shopping)\b/.test(bas) || /\b(shopping list|liste de courses|courses)\b/.test(bas)) intention = 'courses';
else if (/^\/swap\b/.test(bas) || /^(swap|replace|remplace[rz]?)\b/.test(bas)) intention = 'remplacer';
else if (/^\/(today|tonight)\b/.test(bas) || /\b(what'?s for|on mange quoi|qu'?est-ce qu'?on mange|today|tonight|ce soir|ce midi|aujourd'?hui)\b/.test(bas)) intention = 'aujourdhui';

return [{ json: { chatId: chatId, prenom: prenom, texte: texte, intention: intention, reference: reference, minutes: minutes,
  jour: jour, moment: moment, creneau: jour + '_' + moment } }];

const m = $('Parse Intent').first().json;
const d = $input.first().json || {};
if (!m.reference) return [{ json: { ok: false, texte: 'Send /link followed by a plan reference, or tap "Cook with Telegram" on the site.' } }];
if (!d.Reference) return [{ json: { ok: false, texte: 'I can\'t find a plan with the reference ' + m.reference + '.' } }];
if (!d.Email) return [{ json: { ok: false, texte: 'That plan isn\'t tied to an account. Log in on the site, make a plan, then tap "Cook with Telegram" on it.' } }];
return [{ json: { ok: true, chatId: m.chatId, email: d.Email, reference: d.Reference, prenom: m.prenom } }];

const m = $('Parse Intent').first().json;
const n = Math.round(Number(m.minutes) || 0);
if (n < 1 || n > 180) return [{ json: { ok: false, texte: 'How long? Send /timer followed by minutes, e.g. /timer 12 (max 180).' } }];
return [{ json: { ok: true, minutes: n, texte: '⏱ Timer set: ' + n + ' min. I\'ll ping you when it\'s up.' } }];

const NOM_JOUR = { Lun: 'Monday', Mar: 'Tuesday', Mer: 'Wednesday', Jeu: 'Thursday', Ven: 'Friday', Sam: 'Saturday', Dim: 'Sunday' };
const NOM_MOMENT = { midi: 'lunch', soir: 'dinner' };
const ORDRE_JOURS = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
const ORDRE_MOMENTS = ['midi', 'soir'];
function libelle(c) { const p = String(c || '').split('_'); return (NOM_JOUR[p[0]] || p[0]) + ' ' + (NOM_MOMENT[p[1]] || p[1]); }
function rang(c) { const p = String(c || '').split('_'); return ORDRE_JOURS.indexOf(p[0]) * 2 + ORDRE_MOMENTS.indexOf(p[1]); }
function quantite(i) { return [i.quantite || '', i.unite || ''].join(' ').trim(); }
function listeIngredients(r) {
  return (r.ingredients || []).map(function (i) { const q = quantite(i); return '• ' + i.nom + (q ? ' — ' + q : ''); }).join('\n');
}
function infos(r) {
  const x = [];
  if (r.temps) x.push(r.temps + ' min');
  if (r.calories) x.push(r.calories + ' kcal');
  if (r.proteines) x.push(r.proteines + ' g protein');
  return x.join(' · ');
}
function fiche(r, personnes) {
  const l = [r.plat];
  if (infos(r)) l.push(infos(r));
  if (r.ingredients && r.ingredients.length) { l.push(''); l.push('🧺 Ingredients' + (personnes ? ' (for ' + personnes + ')' : '') + ':'); l.push(listeIngredients(r)); }
  if (r.lien) { l.push(''); l.push('🔗 ' + r.lien); }
  return l.join('\n');
}
// The meal for the asked slot, or the next one coming up when that slot is empty.
function repasPour(repas, creneau) {
  const ici = repas.find(function (r) { return r.creneau === creneau; });
  if (ici) return { repas: ici, exact: true };
  const jour = String(creneau).split('_')[0];
  const memeJour = repas.find(function (r) { return String(r.creneau).split('_')[0] === jour; });
  if (memeJour) return { repas: memeJour, exact: false };
  const suivant = repas.find(function (r) { return rang(r.creneau) > rang(creneau); }) || repas[0];
  return { repas: suivant, exact: false };
}
function messageEtape(plat, etapes, i) {
  const e = etapes[i];
  let t = '🍳 ' + plat + ' — step ' + (i + 1) + '/' + etapes.length + '\n\n' + e.texte;
  if (e.minutes) t += '\n\n⏱ About ' + e.minutes + ' min. Send /timer ' + e.minutes + ' and I\'ll ping you.';
  t += '\n\n' + (i + 1 < etapes.length ? '➡️ next · back · repeat · /stop' : '➡️ next to finish · back · repeat');
  t += '\n💬 Stuck? Just ask me.';
  return t;
}
function couper(t) { return t.length > 3900 ? t.slice(0, 3850) + '\n\n… (cut, Telegram limit)' : t; }

const c = $input.first().json, m = $('Parse Intent').first().json;
const r = repasPour(c.repas, m.creneau);
const tete = r.exact ? libelle(r.repas.creneau) + ':' : 'Nothing planned for ' + libelle(m.creneau) + '. Next up, ' + libelle(r.repas.creneau) + ':';
return [{ json: { texte: tete + '\n\n' + fiche(r.repas, c.personnes) + '\n\n➡️ /recipe for every step · /cook to cook it with me' } }];

