// Spoonacular returns sections (main, sauce...), each with numbered steps. Flatten them.
const etapes = [];
$input.all().forEach(function (it) {
  const s = it.json || {};
  const titre = s.name ? String(s.name).trim() : '';
  (s.steps || []).forEach(function (e, k) {
    let minutes = 0;
    if (e.length && /min/i.test(e.length.unit || '')) minutes = Number(e.length.number) || 0;
    if (e.length && /hour/i.test(e.length.unit || '')) minutes = (Number(e.length.number) || 0) * 60;
    etapes.push({ texte: (titre && k === 0 ? '[' + titre + '] ' : '') + String(e.step || '').trim(), minutes: minutes });
  });
});
const ctx = $('Pick Meal').first().json;
return [{ json: Object.assign({}, ctx, { etapes: etapes }) }];

